import subprocess, tempfile, os, re, random, math, sys

EXE='/workspace/executable'

def render(text, args):
    d=tempfile.mkdtemp(dir='/tmp/markup06')
    inf=os.path.join(d,'in.txt'); out=os.path.join(d,'o.svg')
    open(inf,'w').write(text)
    subprocess.run([EXE,inf,out,'--svg']+args,capture_output=True)
    s=open(out).read()
    os.remove(inf); os.remove(out); os.rmdir(d)
    return s

def paths(svg):
    return re.findall(r"<path ([^>]*?)d='([^']*)'", svg)

def f2s(v):
    # emulate Java Float.toString for the values we produce
    import struct
    fv=struct.unpack('f',struct.pack('f',v))[0]
    if fv==int(fv) and abs(fv)<1e7: return '%.1f'%fv
    r=repr(fv)
    return r

def box(tag,w,h):
    L=['+'+'-'*(w-2)+'+']
    for r in range(h-2):
        L.append('|'+(('{%s}'%tag) if r==0 else '').ljust(w-2)+'|')
    L.append('+'+'-'*(w-2)+'+')
    return '\n'.join(L)+'\n'

K=0.5522847498307933

def predict(tag,w,h,scale,fixed):
    cw=int(10*scale); ch=int(14*scale)
    x1=2*cw+cw//2; x2=(w-1+2)*cw+cw//2
    y1=2*ch+ch//2; y2=(h-1+2)*ch+ch//2
    W=x2-x1; H=y2-y1
    mx=(x1+x2)/2.0; my=(y1+y2)/2.0
    off = (H/8.0) if fixed else (cw/2.0)
    if tag=='d':
        dx=W//6; dy=H//8
        return 'M%s %s L%s %s L%s %s Q%s %s %s %s Q%s %s %s %s z'%tuple(map(f2s,[x1,y1,x2,y1,x2,y2,mx+dx,y2-dy,mx,y2,mx-dx,y2+dy,x1,y2]))
    if tag=='s':
        dx=W//6; eh=ch//2
        return ('M%s %s C%s %s %s %s %s %s C%s %s %s %s %s %s M%s %s L%s %s C%s %s %s %s %s %s L%s %s '%tuple(map(f2s,
          [x1,y1, x1+dx,y1+eh, x2-dx,y1+eh, x2,y1,  x2-dx,y1-eh, x1+dx,y1-eh, x1,y1,
           x1,y1, x1,y2, x1+dx,y2+cw, x2-dx,y2+cw, x2,y2, x2,y1])))
    if tag=='o':
        rx=W/2.0; ry=H/2.0
        return 'M%s %s C%s %s %s %s %s %s C%s %s %s %s %s %s C%s %s %s %s %s %s C%s %s %s %s %s %s z'%tuple(map(f2s,
          [mx,y1, mx+K*rx,y1, x2,my-K*ry, x2,my,
                  x2,my+K*ry, mx+K*rx,y2, mx,y2,
                  mx-K*rx,y2, x1,my+K*ry, x1,my,
                  x1,my-K*ry, mx-K*rx,y1, mx,y1]))
    if tag=='c':
        return 'M%s %s L%s %s L%s %s L%s %s z'%tuple(map(f2s,[x1,my,mx,y1,x2,my,mx,y2]))
    if tag=='mo':
        return 'M%s %s L%s %s L%s %s L%s %s z'%tuple(map(f2s,[x1-off,y1,x2+off,y1,x2-off,y2,x1+off,y2]))
    if tag=='tr':
        return 'M%s %s L%s %s L%s %s L%s %s z'%tuple(map(f2s,[x1+off,y1,x2-off,y1,x2+off,y2,x1-off,y2]))
    if tag=='io':
        return 'M%s %s L%s %s L%s %s L%s %s z'%tuple(map(f2s,[x1+off,y1,x2+off,y1,x2-off,y2,x1-off,y2]))

random.seed(7)
fails=0; tot=0
for tag in ['d','s','o','c','mo','tr','io']:
    for trial in range(14):
        w=random.randint(len(tag)+4,25); h=random.randint(3,12)
        scale=random.choice([1,2,3,0.5,1.5,2.5,4,0.75,1.25])
        fixed=random.choice([True,False])
        txt=box(tag,w,h)
        args=['-s',str(scale),'-S']+(['-W'] if fixed else [])
        svg=render(txt,args)
        got=[d for a,d in paths(svg)]
        exp=predict(tag,w,h,scale,fixed)
        tot+=1
        if len(got)!=1 or got[0].strip()!=exp.strip():
            fails+=1
            print('FAIL tag=%s w=%d h=%d s=%s W=%s'%(tag,w,h,scale,fixed))
            print('  exp:',exp)
            print('  got:',got)
print('total',tot,'fails',fails)
